def model(x, iv):
    x=np.asarray(x,dtype=float)
    B=x.shape[0]
    h=np.zeros((B,16))
    for t in range(10):
        h=np.maximum(x[:,[t]]*WX+h@WH,0.0)
        h=iv("h%d"%(t+1),h)
    return h@WO
